<?php
require '../config/config.php';
if (empty($_SESSION['u']) || ($_SESSION['u']['role'] ?? '') === 'anggota') { header('Location:'.$BASE_URL.'/member/dashboard.php'); exit; }
$user=$_SESSION['u'];
function scalar($pdo,$sql){try{return $pdo->query($sql)->fetchColumn() ?: 0;}catch(Throwable $e){return 0;}}
$totalBooks=scalar($pdo,"SELECT COUNT(*) FROM books");
$totalCopies=scalar($pdo,"SELECT COUNT(*) FROM copies");
$availableCopies=scalar($pdo,"SELECT COUNT(*) FROM copies WHERE status='tersedia'");
$borrowedCopies=scalar($pdo,"SELECT COUNT(*) FROM copies WHERE status='dipinjam'");
$totalMembers=scalar($pdo,"SELECT COUNT(*) FROM users WHERE role='anggota'");
$activeLoans=scalar($pdo,"SELECT COUNT(*) FROM loans WHERE returned_at IS NULL");
$overdue=scalar($pdo,"SELECT COUNT(*) FROM loans WHERE returned_at IS NULL AND due_date<CURDATE()");
$visitsToday=scalar($pdo,"SELECT COUNT(*) FROM visits WHERE visit_date=CURDATE()");
$visitsMonth=scalar($pdo,"SELECT COUNT(*) FROM visits WHERE YEAR(visit_date)=YEAR(CURDATE()) AND MONTH(visit_date)=MONTH(CURDATE())");
$topMembers=[];
try{$topMembers=$pdo->query("SELECT u.id,u.name,u.class_name,(SELECT COUNT(*) FROM loans l WHERE l.user_id=u.id)+(SELECT COUNT(*) FROM visits v WHERE v.user_id=u.id) activity,(SELECT COUNT(*) FROM loans l2 WHERE l2.user_id=u.id) loans,(SELECT COUNT(*) FROM visits v2 WHERE v2.user_id=u.id) visits FROM users u WHERE u.role='anggota' ORDER BY activity DESC,u.name LIMIT 5")->fetchAll();}catch(Throwable $e){}
$dueSoon=[];
try{$dueSoon=$pdo->query("SELECT u.name,u.username,b.title,c.code,l.due_date,DATEDIFF(l.due_date,CURDATE()) days_left FROM loans l JOIN users u ON u.id=l.user_id JOIN copies c ON c.id=l.copy_id JOIN books b ON b.id=c.book_id WHERE l.returned_at IS NULL AND l.due_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 7 DAY) ORDER BY l.due_date,l.id LIMIT 8")->fetchAll();}catch(Throwable $e){}
$topBooks=[];
try{$topBooks=$pdo->query("SELECT b.title,COUNT(l.id) total FROM books b LEFT JOIN copies c ON c.book_id=b.id LEFT JOIN loans l ON l.copy_id=c.id GROUP BY b.id,b.title ORDER BY total DESC,b.title LIMIT 5")->fetchAll();}catch(Throwable $e){}
$last7=[];for($i=6;$i>=0;$i--){$date=date('Y-m-d',strtotime("-$i days"));$st=$pdo->prepare("SELECT COUNT(*) FROM loans WHERE loan_date=?");$st->execute([$date]);$last7[]=['label'=>date('d M',strtotime($date)),'value'=>(int)$st->fetchColumn()];}$maxChart=max(1,max(array_column($last7,'value')));
?>
